import {countries} from './map-data.js';
import {wars as originalWars,features,quizzes} from './content.js';
import {Globe} from './globe.js';
import {campaigns,eventType} from './campaigns.js';
import {yearState} from './globe-math.mjs';
const wars=originalWars.map(w=>({...w,events:campaigns[w.id]?.events||w.events}));
import {project,filterWars,filterPlaces,grade} from './core.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let memory={saved:[],learned:[],quizBest:0};let storageOK=true;
try{const v=JSON.parse(localStorage.getItem('jingwei-v1')||'{}');if(v&&typeof v==='object'){memory.saved=Array.isArray(v.saved)?v.saved.filter(x=>typeof x==='string'):[];memory.learned=Array.isArray(v.learned)?v.learned.filter(x=>typeof x==='string'):[];memory.quizBest=Number(v.quizBest)||0}}catch{storageOK=false}
let mode='history',geoTab='countries',selected={type:'war',id:'ww2'},year=1939,query='',region='全部',eventIndex=-1,playTimer=null,globe=null,timeFocused=false,showRoutes=true,showPast=true,followTime=false,lastYear=1939;
let quizIndex=0,answers=Array(quizzes.length).fill(null),score=0,quizFinished=false;
const current=()=>selected.type==='war'?wars.find(w=>w.id===selected.id):selected.type==='country'?countries.find(c=>c.id===selected.id):features.find(f=>f.id===selected.id);
function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),2600)}
function save(){try{localStorage.setItem('jingwei-v1',JSON.stringify(memory))}catch{storageOK=false;toast('浏览器存储不可用，本次会话仍可继续学习。')}updateProgress()}
function updateProgress(){$('savedCount').textContent=memory.saved.length;$('progress').textContent=`已学 ${memory.learned.length} / ${wars.length} 个战争专题${storageOK?' · 本机记录':' · 临时记录'}`}
const key=()=>selected.type+':'+selected.id;
function toggleSaved(){const k=key();memory.saved=memory.saved.includes(k)?memory.saved.filter(s=>s!==k):[...memory.saved,k];save();renderDetail();toast(memory.saved.includes(k)?'已加入我的学习':'已取消收藏')}
function setMode(m){stopPlay();mode=m;query='';region='全部';$('search').value='';$('region').value='全部';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));if(m==='history'){year=lastYear;const active=filterWars(wars,{year});selected={type:'war',id:active[0]?.id||'ww2'};eventIndex=-1}else{year=null;if(m==='geo'){selected={type:'country',id:'CHN'};geoTab='countries'}}resetMap();render()}
function choose(type,id,focus=false){stopPlay();selected={type,id};eventIndex=-1;if(type==='war'&&mode==='history'){const w=current();if(year===null||year<w.start||year>w.end){year=w.start;lastYear=year}}render();if(focus){const d=current(),p=type==='war'&&year!==null?yearState(d,year,campaigns).pos:d.pos;focusAt(p,type==='country'?2.2:2)}if(window.innerWidth<621&&focus)$('globeWrap').scrollIntoView({behavior:'smooth',block:'start'})}
function listData(){if(mode==='history')return filterWars(wars,{query,region,year});const source=geoTab==='countries'?countries:features;return filterPlaces(source,{query,region})}
function renderList(){const quiz=mode==='quiz';$('listTitle').textContent=quiz?'知识挑战':mode==='history'?'历史索引':'地理索引';$('search').closest('label').hidden=quiz;$('region').parentElement.hidden=quiz;$('search').placeholder=mode==='history'?'搜索战争、地区或主题':'搜索国家、首都或地理要点';$('scope').textContent=mode==='history'?(year===null?'全部时期':year+' 年'):(geoTab==='countries'?'国家 / 地区 ⇄':'地理要点 ⇄');if(quiz){$('listCount').textContent=quizzes.length+' 题';$('items').classList.add('quiz-list');$('items').innerHTML=`<div class="empty"><b>把看过的，变成记住的。</b><p>共 ${quizzes.length} 道地理与历史题。每道题都有即时解析，还可返回地图复习。</p><p>最高记录：${memory.quizBest} / ${quizzes.length}</p><button class="primary" id="restartQuiz">重新开始</button></div>`;$('restartQuiz').onclick=restartQuiz;return}$('items').classList.remove('quiz-list');const data=listData();$('listCount').textContent=data.length+(mode==='history'?' 个专题':' 项');$('items').innerHTML=data.length?data.map(d=>{const type=mode==='history'?'war':geoTab==='countries'?'country':'feature';return `<button class="item ${selected.id===d.id&&selected.type===type?'active':''}" data-id="${d.id}" data-type="${type}"><span class="date">${mode==='history'?d.start+' — '+d.end:esc(d.kind||d.continent)}${memory.learned.includes(d.id)?'<span class="check">✓</span>':''}</span><strong>${esc(d.name)}</strong><small>${esc(mode==='history'?d.tags.slice(0,2).join(' · '):d.region)}</small></button>`}).join(''):'<div class="empty">没有匹配的内容。<br>试试其他关键词、地区或年份。<br><button id="clearFilter" class="primary wide">清除筛选</button></div>';$('items').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>choose(b.dataset.type,b.dataset.id,true));if($('clearFilter'))$('clearFilter').onclick=()=>{query='';region='全部';year=null;timeFocused=false;$('search').value='';$('region').value='全部';render()}}
function detailHeading(d,kicker){return `<div class="detail-top"><span class="category">${kicker}</span><button class="bookmark" id="bookmark" aria-label="${memory.saved.includes(key())?'取消收藏':'收藏当前内容'}">${memory.saved.includes(key())?'★':'☆'}</button></div><h2>${esc(d.name)}</h2>`}
function renderDetail(){if(mode==='quiz'){renderQuiz();return}const d=current();if(!d)return;let html='';if(selected.type==='war'){html=detailHeading(d,'CONFLICT STUDY / 战争档案')+`<div class="period">${d.start} — ${d.end}</div><div class="tags">${d.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="summary">${esc(d.summary)}</p>${phaseDetail(d)}<span class="section-label">01 / 为什么发生</span><p>${esc(d.cause)}</p><span class="section-label">02 / 主要参战方</span><p>${esc(d.sides)}</p><div class="geo-callout"><span class="section-label">⌖ 地理如何影响历史</span><p>${esc(d.geo)}</p></div><span class="section-label">03 / 关键节点 · 点击跳至当年</span>${d.events.map((e,i)=>`<button class="event ${i===eventIndex?'active':''} ${year!==null&&e.date===year?'this-year':''} ${year!==null&&e.date>year?'future':''}" data-event="${i}"><strong><span class="event-date">${e.date}</span>${esc(e.name)} ↗</strong><small>${esc(e.text)}</small></button>`).join('')}<span class="section-label">04 / 结果与影响</span><p>${esc(d.result)}</p><button id="markLearned" class="primary wide">${memory.learned.includes(d.id)?'✓ 已完成阅读 · 点击取消':'✓ 标记已学'}</button><a class="source-link" href="${d.url}" target="_blank" rel="noopener noreferrer">阅读参考资料 ↗</a>`}else if(selected.type==='country'){const related=wars.filter(w=>w.countries.includes(d.id));html=detailHeading(d,'GEOGRAPHY / 国家与地区')+`<div class="period">${esc(d.en)}</div><div class="tags"><span class="tag">${esc(d.continent)}</span><span class="tag">${esc(d.region)}</span></div><div class="stat-grid"><div class="stat"><small>所在分区</small><b>${esc(d.region)}</b></div><div class="stat"><small>首都标签 · 数据集参考</small><b>${esc(d.capital||'本比例尺未收录')}</b></div><div class="stat"><small>地图标签经度</small><b>${Math.abs(d.pos[0]).toFixed(1)}° ${d.pos[0]>=0?'E':'W'}</b></div><div class="stat"><small>地图标签纬度</small><b>${Math.abs(d.pos[1]).toFixed(1)}° ${d.pos[1]>=0?'N':'S'}</b></div></div><div class="geo-callout"><span class="section-label">⌖ 观察地图的三个问题</span><p>它位于哪个半球？周围有哪些国家或海域？山地、海岸和陆路通道可能怎样影响它与外界的联系？</p></div><span class="section-label">与这片地域相关的战争</span><p>按当代地理位置关联，不代表当时疆界、国名或参战主体。</p>${related.length?related.map(w=>`<button class="country-link" data-war="${w.id}">${w.name} ↗</button>`).join(''):'<p style="margin-top:10px">当前入门专题尚未收录相关战争，可先从周边区域探索。</p>'}<button id="locateCountry" class="primary wide">⌖ 在地图上定位</button><span class="section-label">资料说明</span><p>Natural Earth 小比例尺参考数据。首都标签不完整，可能滞后；不适合判断现行行政地位或主权。经纬度为制图标签位置，并非首都坐标。</p>`}else{html=detailHeading(d,'FIELD NOTES / 地理要点')+`<div class="tags"><span class="tag">${d.kind}</span><span class="tag">${d.region}</span></div><p class="summary">${d.text}</p><div class="geo-callout"><span class="section-label">⌖ 为什么值得记住</span><p>${d.why}</p></div>${d.war?`<span class="section-label">连接一段历史</span><button class="country-link" data-war="${d.war}">${wars.find(w=>w.id===d.war).name} ↗</button>`:''}<button id="locateCountry" class="primary wide">⌖ 在地图上定位</button><span class="section-label">读图提示</span><p>圆点表示大致位置，山脉、流域与海域不是一个点。请结合完整地形图继续学习其范围。</p><a class="source-link" href="https://www.naturalearthdata.com/downloads/110m-physical-vectors/" target="_blank" rel="noopener noreferrer">Natural Earth 自然地理数据 ↗</a>`}$('detail').innerHTML=html;$('bookmark').onclick=toggleSaved;document.querySelectorAll('[data-war]').forEach(b=>b.onclick=()=>{setMode('history');choose('war',b.dataset.war,true)});document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{stopPlay();eventIndex=Number(b.dataset.event);const e=d.events[eventIndex];year=e.date;lastYear=year;render();focusAt(e.pos,3);toast(`${e.date} · ${e.name}`)});document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{const route=yearState(d,year,campaigns).routes[Number(b.dataset.route)];if(route)globe?.focus(route.to,2.9)});if($('markLearned'))$('markLearned').onclick=()=>{memory.learned=memory.learned.includes(d.id)?memory.learned.filter(x=>x!==d.id):[...memory.learned,d.id];save();renderList();renderDetail()};if($('locateCountry'))$('locateCountry').onclick=()=>focusAt(d.pos,selected.type==='country'?2.6:3)}
function phaseDetail(w){if(year===null)return '<div class="year-context"><span class="context-kicker">历史总览</span><p>点击一个关键节点，进入该年份，观看当年事件与行动方向。</p></div>';const state=yearState(w,year,campaigns);return `<div class="year-context"><span class="context-kicker">${year} / 年度形势</span><h3>${esc(state.title)}</h3><p>${esc(state.summary)}</p>${state.routes.map((r,i)=>`<button class="route-item ${r.side}" data-route="${i}"><i class="route-dot"></i><b>${esc(r.label)}</b> ↗</button>`).join('')}<small>动态方向线为示意，不是精确行军轨迹或战线。</small><a class="source-link" href="${state.source||w.url}" target="_blank" rel="noopener noreferrer">本阶段参考资料 ↗</a></div>`}
function initMap(){try{globe=new Globe($('globeMount'),countries,{onSelect:m=>{if(mode==='quiz')return;if(m.type==='event'){stopPlay();selected={type:'war',id:m.warId};eventIndex=m.index;year=m.date;lastYear=year;render();globe.focus(m.pos,2.8)}else choose(m.type,m.id,m.type!=='country')},onView:v=>{const[lon,lat]=v.pos;$('viewReadout').textContent=`${Math.abs(lon).toFixed(1)}° ${lon>=0?'E':'W'} · ${Math.abs(lat).toFixed(1)}° ${lat>=0?'N':'S'} · ${(3.6/v.distance).toFixed(1)}×`; $('globeWrap').dataset.view=JSON.stringify(v)}});if(matchMedia('(prefers-reduced-motion: reduce)').matches){globe.setOptions({effects:false});$('effects').setAttribute('aria-pressed','false')}}catch(error){$('globeMount').innerHTML='<div class="webgl-error">此浏览器暂时无法启用 3D 图形。<br>请使用支持 WebGL 的浏览器并开启硬件加速。<br>下方时间轴与知识卡仍可使用。</div>';$('globeStatus').textContent='3D 图形不可用';console.error('Globe initialization:',error)}}
function resetMap(){globe?.reset()}
function focusAt(pos,z=2){globe?.focus(pos,z>=3?2.45:3.1)}
function changeZoom(factor){globe?.zoom(factor)}
function renderMarkers(){const markers=[],arcs=[],related=new Set(),d=current();if(mode==='history'){const list=listData();if(year===null){for(const w of list)markers.push({type:'war',id:w.id,name:w.name,pos:w.pos,selected:selected.id===w.id,kind:'battle'})}else for(const w of list){const st=yearState(w,year,campaigns);for(const e of st.current){markers.push({...e,type:'event',warId:w.id,index:w.events.indexOf(e),selected:selected.id===w.id,kind:eventType(e)})}if(!st.current.length)markers.push({type:'war',id:w.id,name:w.name+' · 持续',pos:w.pos,selected:selected.id===w.id,kind:'ongoing'});if(selected.type==='war'&&selected.id===w.id){if(showPast)for(const e of st.past)markers.push({...e,type:'event',warId:w.id,index:w.events.indexOf(e),past:true,kind:eventType(e)});w.countries.forEach(id=>related.add(id))}if(showRoutes)arcs.push(...st.routes)}}else if(mode==='geo'){const items=geoTab==='features'?listData():features;for(const f of items){if(f.kind)markers.push({...f,type:'feature',kind:'feature',selected:selected.id===f.id})}}if(selected.type==='country'&&mode!=='quiz')markers.push({...d,type:'country',kind:'country',selected:true});globe?.setData({markers,arcs,selectedCountry:selected.type==='country'&&mode!=='quiz'?selected.id:null,related:[...related],year});}
function timelineUI(){const w=selected.type==='war'?current():null;if(!w)timeFocused=false;const min=timeFocused?w.start:1756,max=timeFocused?w.end:1991;$('year').min=min;$('year').max=max;$('year').value=year??Math.max(min,Math.min(max,lastYear));$('year').disabled=min===max;$('year').setAttribute('aria-valuetext',year===null?'全部时期':year+'年');$('yearLabel').textContent=year===null?'总览':year;$('globeYear').textContent=mode==='history'?(year===null?'1756—1991':year):mode==='geo'?'EARTH':'QUIZ';$('focusTime').setAttribute('aria-pressed',String(timeFocused));$('focusTime').disabled=!w;$('focusTime').textContent=timeFocused?'返回完整时间轴':'聚焦当前战争';const ticks=timeFocused?[...new Set([min,Math.round(min+(max-min)/4),Math.round(min+(max-min)/2),Math.round(min+(max-min)*.75),max])]:[1756,1800,1850,1900,1945,1991];$('yearTicks').innerHTML=ticks.map(y=>`<span>${y}</span>`).join('');const phases=w?[...new Set(w.events.map(e=>e.date))]:[];$('phaseStrip').innerHTML=mode==='history'&&w?phases.map(y=>`<button data-phase="${y}" class="${year===y?'active':''}">${y}<span>${w.events.filter(e=>e.date===y).length} 节点</span></button>`).join(''):'';$('phaseStrip').querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{stopPlay();setYear(b.dataset.phase)});$('prevYear').disabled=year!==null&&year<=min;$('nextYear').disabled=year!==null&&year>=max;}
function situationUI(){const list=mode==='history'?listData():[];let title,text,extra='';if(mode==='history'){if(year===null){title='全时段 · 19 个战争专题';text='选择战争或拖动年份，进入当年形势。总览中的地点不表示这些战争同时发生。'}else if(!list.length){title=year+' 年 · 当前筛选暂无已收录战争';text='这不代表当年没有战争。本工具提供代表性专题，未覆盖全部冲突。'}else if(selected.type==='war'&&list.some(w=>w.id===selected.id)){const st=yearState(current(),year,campaigns);title=year+' · '+st.title;text=st.summary;extra=st.current.length+' 个本年节点 · '+st.routes.length+' 条方向示意'}else{title=year+' 年 · '+list.length+' 个已收录冲突';text=list.map(w=>w.name).join(' · ')}}else{title=mode==='geo'?'把世界握在手中':'转动地球，建立空间记忆';text=mode==='geo'?'拖动旋转、滚轮或双指缩放；点击国家或地理要点。':'在右侧回答问题，查看解析后可跳回地球复习。'}$('situation').innerHTML=`<span class="situation-count">${mode==='history'?list.length:'◎'}</span><div><h3>${esc(title)}</h3><p>${esc(text)}</p>${extra?'<small>'+extra+'</small>':''}</div>`;if(globe)$('globeStatus').textContent=mode==='history'?(year===null?'全时段 · 非同时发生':list.length+' 个已收录冲突 · 年度视图'):'拖动地球 · 探索世界';}
function setYear(v){year=Math.max(1756,Math.min(1991,Math.round(Number(v))));lastYear=year;eventIndex=-1;const list=filterWars(wars,{year,region,query});if(list.length&&(selected.type!=='war'||!list.some(w=>w.id===selected.id)))selected={type:'war',id:list[0].id};if(timeFocused&&selected.type==='war'){const w=current();if(year<w.start||year>w.end)timeFocused=false}render();if(followTime&&list.length&&selected.type==='war')globe?.focus(yearState(current(),year,campaigns).pos,3.1);}
function stopPlay(){if(playTimer)clearInterval(playTimer);playTimer=null;$('play').textContent='▶';$('play').setAttribute('aria-label','播放时间轴');$('play').setAttribute('aria-pressed','false')}
function startPlay(){stopPlay();let min=Number($('year').min),max=Number($('year').max);if(min===max){toast('该专题在同一年内，可点击节点逐一查看。');return}if(year===null)setYear(Math.max(min,Math.min(max,lastYear)));if(year>=max)setYear(min);$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','暂停时间轴');$('play').setAttribute('aria-pressed','true');playTimer=setInterval(()=>{if(year>=max){stopPlay();return}setYear(year+1)},1600/Number($('playSpeed').value));}
function render(){renderList();renderDetail();renderMarkers();timelineUI();situationUI();$('timeline').hidden=mode!=='history';$('mapTitle').textContent=mode==='geo'?'3D 地球 · 地理探索':mode==='quiz'?'3D 地球 · 知识挑战':year===null?'3D 地球 · 历史总览':year+' 年 · 战争形势';$('mapTip').textContent='拖动旋转 · 滚轮 / 双指缩放 · 点击地点探索';updateProgress();if(mode==='history'&&year!==null&&!listData().length){$('detail').innerHTML=`<div class="category">TIMELINE / 时间定位</div><h2>${year} 年</h2><p class="summary">没有符合当前筛选的已收录战争专题。</p><p>这并不表示当年世界没有战争。试着切换年份或清除搜索条件。</p><button class="primary wide" id="backAll">浏览全部专题</button>`;$('backAll').onclick=overview;}}
function overview(){stopPlay();year=null;timeFocused=false;query='';region='全部';$('search').value='';$('region').value='全部';render();resetMap()}
function restartQuiz(){quizIndex=0;answers=Array(quizzes.length).fill(null);score=0;quizFinished=false;renderQuiz()}
function renderQuiz(){if(quizFinished){$('detail').innerHTML=`<span class="category">CHALLENGE COMPLETED</span><h2>完成一次世界巡游。</h2><div class="period">${score} / ${quizzes.length}</div><p class="summary">${score===quizzes.length?'全部答对！试着用自己的话解释这些地理联系。':'记忆来自不断建立联系。下面的错题值得再看一次。'}</p>${quizzes.map((q,i)=>!grade(q,answers[i])?`<div class="geo-callout"><span class="section-label">${q.question}</span><p>${q.explanation}</p></div>`:'').join('')}<button id="again" class="primary wide">再挑战一次</button><button id="goExplore" class="country-link">返回地图</button>`;$('again').onclick=restartQuiz;$('goExplore').onclick=()=>setMode('geo');return}const q=quizzes[quizIndex],answered=answers[quizIndex]!==null;$('detail').innerHTML=`<span class="category">KNOWLEDGE CHALLENGE</span><div class="quiz-track"><div style="width:${quizIndex/quizzes.length*100}%"></div></div><div class="period">${String(quizIndex+1).padStart(2,'0')} / ${quizzes.length}</div><h2 style="font-size:22px">${q.question}</h2>${q.options.map((s,i)=>`<button class="quiz-option ${answered?(i===q.answer?'correct':i===answers[quizIndex]?'wrong':''):''}" data-answer="${i}" ${answered?'disabled':''}>${'ABCD'[i]} · ${s}</button>`).join('')}${answered?`<div class="feedback"><b>${grade(q,answers[quizIndex])?'✓ 回答正确':'再记住这个联系'}</b><p>${q.explanation}</p></div><div class="quiz-nav"><button id="reviewQuiz" class="country-link">地图复习 ↗</button><button id="nextQuiz" class="primary">${quizIndex===quizzes.length-1?'查看成绩':'下一题 →'}</button></div>`:'<p style="margin-top:18px">选择一个答案，查看解释。每题首次选择计入成绩。</p>'}`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(answers[quizIndex]!==null)return;answers[quizIndex]=Number(b.dataset.answer);if(grade(q,answers[quizIndex]))score++;renderQuiz()});if(answered){$('nextQuiz').onclick=()=>{if(quizIndex===quizzes.length-1){quizFinished=true;memory.quizBest=Math.max(memory.quizBest,score);save();renderList()}else quizIndex++;renderQuiz()};$('reviewQuiz').onclick=()=>{const isWar=wars.some(w=>w.id===q.ref);setMode(isWar?'history':'geo');if(!isWar)geoTab='features';choose(isWar?'war':'feature',q.ref,true);toast('已保留答题进度，点击“知识挑战”可继续。')}}}
function showModal(content){$('modalContent').innerHTML=content;$('modal').showModal()}
function showSources(){showModal(`<span class="modal-kicker">READING ROOM</span><h2>资料来源与阅读说明</h2><p>本工具收录 ${wars.length} 个代表性战争专题、${features.length} 个地理要点及 ${countries.length} 个国家／地区制图单元，面向入门学习，并非完整战争史或国家名录。</p><p><b>时间范围：</b>1756—1991，涵盖部分近代与现代史。战争起止年份可能因历史分期不同而异，个别专题已在卡片说明。</p><p><b>地图：</b>Natural Earth 1:110m 国家与城市数据，获取于 2026-10-25。球面使用当代边界纹理；首都标签可能滞后，小国与小岛可能未收录。边界沿用数据源表达，不表示本工具对争议主权的立场。</p><p><b>历史图层：</b>浅绿色区域只是与事件相关的当代地区，不是当时的领土、势力范围或完整参战国图。地点为约略定位，按年汇总事件，不展示逐月前线。橙色节点为当年战事、绿色节点为政治或停战事件，淡色点为此前节点。动画弧线只表示行动大方向，颜色用于区分方向组，不表示永久阵营；点的大小与闪动不表示伤亡或战斗强度。原因与地理影响为简要综合解释，读者可对照不同史学视角。</p><p><b>学习记录：</b>收藏、已学专题和测验最高分保存在此浏览器；不会自动跨设备同步。</p><div class="reading-list"><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">Natural Earth · 地图数据与公共领域许可 ↗</a>${Object.values(campaigns).map(c=>`<a href="${c.source}" target="_blank" rel="noopener noreferrer">年度阶段补充资料 ↗</a>`).join('')}${wars.map(w=>`<a href="${w.url}" target="_blank" rel="noopener noreferrer">${w.name} · 原始参考页面 ↗</a>`).join('')}</div>`)}
function showCollection(){const lookup=k=>{const[type,id]=k.split(':');return {type,id,d:type==='war'?wars.find(w=>w.id===id):type==='country'?countries.find(c=>c.id===id):features.find(f=>f.id===id)}};const rows=memory.saved.map(lookup).filter(r=>r.d);showModal(`<span class="modal-kicker">YOUR FIELD JOURNAL</span><h2>我的学习</h2><p>已学 ${memory.learned.length} 个战争专题 · 测验最高分 ${memory.quizBest}/${quizzes.length}</p>${rows.length?rows.map(r=>`<div class="saved-row"><button data-open="${r.type}:${r.id}">${esc(r.d.name)} ↗</button><button data-remove="${r.type}:${r.id}" aria-label="移除${esc(r.d.name)}">×</button></div>`).join(''):'<p>还没有收藏。点击知识卡右上角的 ☆，收集想继续了解的地点与历史。</p>'}<p>记录保存在当前浏览器。</p>`);document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const[type,id]=b.dataset.open.split(':');$('modal').close();setMode(type==='war'?'history':'geo');if(type==='feature')geoTab='features';choose(type,id,true)});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{memory.saved=memory.saved.filter(s=>s!==b.dataset.remove);save();$('modal').close();showCollection()})}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
$('search').oninput=e=>{query=e.target.value;render()};$('region').onchange=e=>{region=e.target.value;render()};
$('scope').onclick=()=>{if(mode==='geo'){geoTab=geoTab==='countries'?'features':'countries';query='';$('search').value='';render()}else overview()};
$('year').oninput=e=>{stopPlay();setYear(e.target.value)};$('allYears').onclick=overview;
document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{stopPlay();timeFocused=false;query='';region='全部';$('search').value='';$('region').value='全部';setYear(b.dataset.year)});
$('play').onclick=()=>playTimer?stopPlay():startPlay();$('playSpeed').onchange=()=>{if(playTimer)startPlay()};
$('prevYear').onclick=()=>{stopPlay();setYear(Math.max(Number($('year').min),(year??lastYear)-1))};$('nextYear').onclick=()=>{stopPlay();setYear(Math.min(Number($('year').max),(year??lastYear)+1))};
$('focusTime').onclick=()=>{stopPlay();if(selected.type!=='war')return;timeFocused=!timeFocused;const w=current();if(timeFocused&&(year===null||year<w.start||year>w.end)){year=w.start;lastYear=year}render()};
$('routesToggle').onchange=e=>{showRoutes=e.target.checked;renderMarkers()};$('pastToggle').onchange=e=>{showPast=e.target.checked;renderMarkers()};$('followToggle').onchange=e=>{followTime=e.target.checked};
for(const[id,option]of [['autoRotate','autoRotate'],['effects','effects'],['gridToggle','grid'],['labelsToggle','labels']])$(id).onclick=()=>{const value=$(id).getAttribute('aria-pressed')!=='true';$(id).setAttribute('aria-pressed',String(value));globe?.setOptions({[option]:value})};
$('zoomIn').onclick=()=>changeZoom(1.3);$('zoomOut').onclick=()=>changeZoom(1/1.3);$('resetMap').onclick=resetMap;$('sources').onclick=showSources;$('help').onclick=showSources;$('collection').onclick=showCollection;$('closeModal').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close()}};$('discover').onclick=()=>{setMode('geo');geoTab='features';choose('feature','suezgeo',true)};
initMap();render();
